import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-react-react-useunload-hook":{"intro":"In this lab, we will explore the useUnload hook in React, which allows us to handle the beforeunload window event. The purpose of this lab is to demonstrate how to use this hook to create a callback function that will be triggered when the user tries to close the window. We will also learn how to perform cleanup after the component is unmounted. By the end of this lab, you will have a better understanding of how to manage window events in React.","steps":[{"title":"React useUnload Hook","body":["The beforeunload window event can be handled using the following steps:","• Create a ref for the callback function, fn, using the useRef() hook. • Use the useEffect() hook and EventTarget.addEventListener() to handle the 'beforeunload' event, which is triggered when the user is about to close the window. • Use EventTarget.removeEventListener() to perform cleanup after the component is unmounted."],"code":[{"lang":"jsx","text":"const useUnload = (fn) => {\n  const callbackRef = React.useRef(fn);\n\n  React.useEffect(() => {\n    const callback = callbackRef.current;\n    window.addEventListener(\"beforeunload\", callback);\n    return () => {\n      window.removeEventListener(\"beforeunload\", callback);\n    };\n  }, [callbackRef]);\n};\n\nconst App = () => {\n  useUnload((e) => {\n    e.preventDefault();\n    const exit = confirm(\"Are you sure you want to leave?\");\n    if (exit) window.close();\n  });\n\n  return <div>Try closing the window.</div>;\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<App />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useUnload Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-increment-decrement-counter":{"intro":"In this challenge you will be developing a counter game aka increment decrement counter using React hooks i.e with useState and useEffect in which you can click a button to increase the count value. This you can play with your friends and challenge them to click click click... as much as possible in a given time.","steps":[{"title":"Counter Game","body":["To get started, open the editor. You can see the following files from your editor.","• To install the project dependencies, use the following command:","• Please complete this challenge in the components/HomePage/HomePage.js file. • Use the useState hook to define two state variables: count and timer. • Use the useEffect hook to start the timer when the timer state variable changes. • Check the timer value. If it is zero, the effect returns early and doesn't do anything. • If the timer value is not zero, it sets up an interval that decrements the timer value by 1 every second (1000 milliseconds). • Return a cleanup function that clears the interval when the component is unmounted or when the timer value changes.","Once you have completed the code, run it with the following command:"],"code":[{"lang":"txt","text":"├── public\n├── src\n│   ├── components\n│   │  └── HomePage\n│   │       ├── HomePage.css\n│   │       └── HomePage.js\n│   ├── App.js\n│   ├── index.css\n│   └── index.js\n├── package-lock.json\n└── package.json"},{"lang":"bash","text":"npm start"}]}],"commands":["npm i","npm start"],"reference":[{"path":"HomePage.js","text":"import React, { useEffect, useState } from \"react\";\nimport \"./HomePage.css\";\n\nfunction HomePage() {\n  const [count, setCount] = useState(0);\n  const [timer, setTimer] = useState(0);\n  useEffect(() => {\n    if (timer === 0) return;\n\n    const interval = setInterval(() => {\n      setTimer(timer - 1);\n    }, 1000);\n\n    return () => {\n      clearInterval(interval);\n    };\n  }, [timer]);\n\n  return (\n    <div className=\"home-container\">\n      <div className=\"home-timer\">timer:{timer}</div>\n      <div className=\"home-count\">{count}</div>\n      <button\n        className=\"home-btn-start btn\"\n        onClick={() => {\n          setTimer(10);\n          setCount(0);\n        }}\n        disabled={timer !== 0}\n      >\n        start\n      </button>\n      <button\n        className=\"home-btn-click btn\"\n        onClick={() => setCount(count + 1)}\n        disabled={timer === 0}\n      >\n        click me\n      </button>\n      <button\n        className=\"home-btn-reset btn\"\n        onClick={() => {\n          setCount(0);\n          setTimer(0);\n        }}\n      >\n        reset\n      </button>\n    </div>\n  );\n}\n\nexport default HomePage;"}],"source":"Vasu7389/react-project-ideas · by Lotus-7 · CC-BY-4.0"},"labex-react-reusable-react-custom-form-component":{"intro":"In this challenge you will be developing a reusable custom form aka submit form in React with functional component in which you can add as much input fields and buttons as you want by sending them as props. You can use that SINGLE component in your future projects too to have login form, registration form or a data creation/updation form for any CRUD functionality.","steps":[{"title":"Custom Form","body":["To get started, open the editor. You can see the following files from your editor.","• To install the project dependencies, use the following command:","Once you have completed the code, run it with the following command:","The finished result is as follows:"],"code":[{"lang":"txt","text":"├── public\n├── src\n│   ├── components\n│   │   └── CustomForm\n│   │       ├── CustomForm.css\n│   │       └── CustomForm.js\n│   ├── App.js\n│   ├── index.css\n│   └── index.js\n├── package-lock.json\n└── package.json"},{"lang":"bash","text":"npm start"}]}],"commands":["npm i","npm start"],"reference":[{"path":"App.js","text":"import { useRef, useState } from \"react\";\nimport CustomForm from \"./components/CustomForm/CustomForm\";\n\nfunction App() {\n  const usernameRef = useRef();\n  const passwordRef = useRef();\n  const handleLogin = () => {\n    console.log(\"login\");\n    console.log(usernameRef.current.value);\n    console.log(passwordRef.current.value);\n    alert(\n      \"Username: \" +\n        usernameRef.current.value +\n        `\\n` +\n        \"Password: \" +\n        passwordRef.current.value\n    );\n  };\n  const handleRegister = () => {\n    console.log(\"register\");\n    console.log(usernameRef.current.value);\n    console.log(passwordRef.current.value);\n  };\n  return (\n    <div className=\"App\">\n      <CustomForm\n        username={{\n          type: \"text\",\n          label: \"Username\",\n          placeholder: \"Enter Username\",\n          ref: usernameRef,\n          isInput: true\n        }}\n        password={{\n          type: \"password\",\n          label: \"Password\",\n          placeholder: \"Enter Password\",\n          ref: passwordRef,\n          isInput: true\n        }}\n        loginButton={{\n          handler: handleLogin,\n          buttonText: \"Login\",\n          isInput: false\n        }}\n        registerButton={{\n          handler: handleRegister,\n          buttonText: \"Register\",\n          isInput: false\n        }}\n      />\n    </div>\n  );\n}\n\nexport default App;"}],"source":"Vasu7389/react-project-ideas · by Lotus-7 · CC-BY-4.0"},"labex-react-develop-tic-tac-toe-game-with-react":{"intro":"In this challenge, you will learn how to develop a dinosaur-themed game using React, incorporating concepts such as useRef for DOM element references, useState for managing game state, and useEffect for handling game logic and event listeners.","steps":[{"title":"Dino Game","body":["To get started, open the editor. You can see the following files from your editor.","• To install the project dependencies, use the following command:","• Please complete this challenge in the src/components/Dino/Dino.js file. • Initialize two useRef hooks: dinoRef and cactusRef. These hooks will be used to reference the dinosaur and cactus DOM elements. • Initialize a useState hook called score with an initial value of 0. This hook will keep track of the player's score. • Define the jump function. It adds the class \"jump\" to the dinosaur's DOM element referenced by dinoRef. This triggers a CSS animation that makes the dinosaur jump. After a timeout of 300 milliseconds, the \"jump\" class is removed, bringing the dinosaur back to its original position. • Use the useEffect hook to…","Once you have completed the code, run it with the following command:"],"code":[{"lang":"txt","text":"├── public\n├── src\n│   ├──components\n│   │  └── Dino\n│   │       ├── img\n│   │       │   ├── cactus.png\n│   │       │   └── trex.png\n│   │       ├── Dino.css\n│   │       └── Dino.js\n│   ├── App.js\n│   ├── App.css\n│   ├── index.css\n│   └── index.js\n├── package-lock.json\n└── package.json"},{"lang":"bash","text":"npm start"}]}],"commands":["npm i","npm start"],"reference":[{"path":"Dino.js","text":"import React, { useEffect, useRef, useState } from \"react\";\nimport \"./Dino.css\";\n\nfunction Dino() {\n  const dinoRef = useRef();\n  const cactusRef = useRef();\n  const [score, setScore] = useState(0);\n\n  const jump = () => {\n    if (!!dinoRef.current && dinoRef.current.classList != \"jump\") {\n      dinoRef.current.classList.add(\"jump\");\n      setTimeout(function () {\n        dinoRef.current.classList.remove(\"jump\");\n      }, 300);\n    }\n  };\n\n  useEffect(() => {\n    const isAlive = setInterval(function () {\n      // get current dino Y position\n      const dinoTop = parseInt(\n        getComputedStyle(dinoRef.current).getPropertyValue(\"top\")\n      );\n\n      // get current cactus X position\n      let cactusLeft = parseInt(\n        getComputedStyle(cactusRef.current).getPropertyValue(\"left\")\n      );\n\n      // detect collision\n      if (cactusLeft < 40 && cactusLeft > 0 && dinoTop >= 140) {\n        // collision\n        alert(\"Game Over! Your Score : \" + score);\n        setScore(0);\n      } else {\n        setScore(score + 1);\n      }\n    }, 10);\n\n    return () => clearInterval(isAlive);\n  });\n\n  useEffect(() => {\n    document.addEventListener(\"keydown\", jump);\n    return () => document.removeEventListener(\"keydown\", jump);\n  }, []);\n\n  return (\n    <div className=\"game\">\n      Score : {score}\n      <div id=\"dino\" ref={dinoRef}></div>\n      <div id=\"cactus\" ref={cactusRef}></div>\n    </div>\n  );\n}\n\nexport default Dino;"}],"source":"Vasu7389/react-project-ideas · by Lotus-7 · CC-BY-4.0"},"labex-react-build-drag-and-drop-react-board":{"intro":"In this challenge we will develop a react drag and drop similar to JIRA board without any external library.","steps":[{"title":"Drag Drop","body":["To get started, open the editor. You can see the following files from your editor.","• To install the project dependencies, use the following command:","• Please complete this challenge in the App.js file. • The onDragStart function is defined. It is an event handler for the dragstart event on a task card. It sets the data transfer data to the task's name property, which will be used to identify the task when it's dropped. • The onDrop function is defined. It is an event handler for the drop event on the task board. It retrieves the task's name from the data transfer data, updates the category of the task in the tasks state based on the drop location (cat), and sets the updated tasks state using setTasks.","Once you have completed the code, run it with the following command:"],"code":[{"lang":"txt","text":"├── public\n├── src\n│   ├── App.js\n│   ├── App.css\n│   ├── index.css\n│   └── index.js\n├── package-lock.json\n└── package.json"},{"lang":"bash","text":"npm start"}]}],"commands":["npm i","npm start"],"reference":[{"path":"App.js","text":"import { useState } from \"react\";\nimport \"./App.css\";\n\nfunction App() {\n  //state with default data\n  const [tasks, setTasks] = useState([\n    { name: \"STORY-4513: Add tooltip\", category: \"wip\", bgcolor: \"lightblue\" },\n    {\n      name: \"STORY-4547: Fix search bug\",\n      category: \"wip\",\n      bgcolor: \"lightgrey\"\n    },\n    {\n      name: \"STORY-4525: New filter option\",\n      category: \"complete\",\n      bgcolor: \"lightgreen\"\n    },\n    {\n      name: \"STORY-4526: Remove region filter\",\n      category: \"complete\",\n      bgcolor: \"#ee9090\"\n    },\n    {\n      name: \"STORY-4520: Improve performance\",\n      category: \"complete\",\n      bgcolor: \"#eeed90\"\n    }\n  ]);\n\n  //this event is for the dragged task card.\n  //this is required to save unique id in the dom event so that when we drop it we would know the card id\n  const onDragStart = (event, id) => {\n    event.dataTransfer.setData(\"id\", id);\n  };\n\n  //fetches the card id and based on that update the status/category of that card in tasks state\n  const onDrop = (event, cat) => {\n    let id = event.dataTransfer.getData(\"id\");\n    let newTasks = tasks.filter((task) => {\n      if (task.name === id) {\n        task.category = cat;\n      }\n      return task;\n    });\n\n    setTasks([...newTasks]);\n  };\n\n  //method to filter tasks beased on their status\n  const getTask = () => {\n    const tasksToRender = {\n      wip: [],\n      complete: []\n    };\n\n    tasks.forEach((t) => {\n      tasksToRender[t.category].push(\n        <div\n          key={t.name}\n          onDragStart={(e) => onDragStart(e, t.name)}\n          draggable\n          className=\"task-card\"\n          style={{ backgroundColor: t.bgcolor }}\n        >\n          {t.name}\n        </div>\n      );\n    });\n\n    return tasksToRender;\n  };\n\n  return (\n    <div className=\"drag-drop-container\">\n      <h2 className=\"drag-drop-header\">JIRA BOARD: Sprint 21U</h2>\n      <div className=\"drag-drop-board\">\n        <div\n          className=\"wip\"\n          onDragOver={(e) => e.preventDefault()}\n          onDrop={(e) => {\n            onDrop(e, \"wip\");\n          }}\n        >\n          <div className=\"task-header\">In-PROGRESS</div>\n          {getTask().wip}\n        </div>\n        <div\n          onDragOver={(e) => e.preventDefault()}\n          onDrop={(e) => onDrop(e, \"complete\")}\n        >\n          <div className=\"task-header\">COMPLETED</div>\n          {getTask().complete}\n        </div>\n      </div>\n    </div>\n  );\n}\n\nexport default App;"}],"source":"Vasu7389/react-project-ideas · by Lotus-7 · CC-BY-4.0"},"labex-react-input-of-skills":{"intro":"In this challenge we will develop react tag input component which can add tags without any external library.","steps":[{"title":"Input of Skills","body":["To get started, open the editor. You can see the following files from your editor.","• To install the project dependencies, use the following command:","Once you have completed the code, run it with the following command:","The finished result is as follows:"],"code":[{"lang":"txt","text":"├── public\n├── src\n│   ├── components\n│   │   └── TagInput.js\n│   ├── App.css\n│   ├── App.js\n│   ├── index.css\n│   └── index.js\n├── package-lock.json\n└── package.json"},{"lang":"bash","text":"npm start"}]}],"commands":["npm i","npm start"],"reference":[{"path":"TagInput.js","text":"import React, { useState } from \"react\";\n\nconst containerStyle = {\n  padding: \"20px\",\n  display: \"inline-block\",\n  width: \"300px\",\n  border: \"1px solid darkgrey\",\n  borderRadius: \"10px\",\n  background: \"#EAEAEA\"\n};\n\nconst inputStyle = {\n  display: \"inline-block\",\n  fontSize: \"0.9em\",\n  margin: \"5px\",\n  width: \"90%\",\n  border: \"0\",\n  padding: \"10px\",\n  borderRadius: \"10px\",\n  marginTop: \"1rem\"\n};\n\nconst tagStyle = {\n  display: \"inline-block\",\n  backgroundColor: \"#3C4048\",\n  margin: \"5px\",\n  padding: \"4px 10px\",\n  borderRadius: \"10px\",\n  cursor: \"pointer\",\n  color: \"white\"\n};\n\nconst TagInput = () => {\n  //state to save all user input in an array\n  const [tags, setTags] = useState([]);\n\n  const handleAddTag = (e) => {\n    //if key not enter then don't add it\n    if (e.key !== \"Enter\") return;\n\n    const input = e.target.value;\n\n    //if input is empty or \"\" then don't add it\n    if (!input) return;\n    //if the input already been added\n    if (tags.includes(input)) return;\n\n    setTags([...tags, input]);\n    e.target.value = \"\";\n  };\n\n  const onDeleteTag = (tag) => {\n    const filteredTags = tags.filter((t) => t !== tag);\n    setTags(filteredTags);\n  };\n\n  return (\n    <div style={containerStyle}>\n      <h2>ADD SKILLS</h2>\n      {tags.map((tag) => (\n        <span key={tag} onClick={() => onDeleteTag(tag)} style={tagStyle}>\n          &#x2716; {tag}\n        </span>\n      ))}\n      <input\n        style={inputStyle}\n        onKeyUp={(e) => handleAddTag(e)}\n        type=\"text\"\n        placeholder=\"Enter value...\"\n      />\n    </div>\n  );\n};\n\nexport default TagInput;"}],"source":"Vasu7389/react-project-ideas · by Lotus-7 · CC-BY-4.0"},"labex-react-build-responsive-react-portfolio":{"intro":"In this tutorial we will build a responsive Portfolio Project in React from scratch. This tutorial will teach you how you can develop your own modern 2023 ready personal portfolio website using reactjs, html & css.","steps":[{"title":"Personal Portfolio","body":["To get started, open the editor. You can see the following files from your editor.","• To install the project dependencies, use the following command:","Once you have completed the code, run it with the following command:","The finished result is as follows:"],"code":[{"lang":"txt","text":"├── public\n├── src\n│   ├── components\n│   ├── App.css\n│   ├── App.js\n│   ├── index.css\n│   └── index.js\n├── package-lock.json\n└── package.json"},{"lang":"bash","text":"npm start"}]}],"commands":["npm i","npm start"],"reference":[{"path":"App.js","text":"import React, { useEffect, useState } from \"react\";\nimport ArrowUpwardIcon from \"@material-ui/icons/ArrowUpward\";\nimport \"./App.css\";\nimport AboutPage from \"./components/AboutPage\";\nimport ContactPage from \"./components/ContactPage\";\nimport HomePage from \"./components/HomePage\";\nimport ProjectPage from \"./components/ProjectPage\";\nimport SkillPage from \"./components/SkillPage\";\nimport EducationPage from \"./components/EducationPage\";\n\nexport default function App() {\n  const [showBackToTopBtn, setShowBackToTopBtn] = useState(false);\n\n  const toggleVisible = () => {\n    const scrolled = document.documentElement.scrollTop;\n    if (scrolled > 500) {\n      setShowBackToTopBtn(true);\n    } else if (scrolled <= 500) {\n      setShowBackToTopBtn(false);\n    }\n  };\n\n  useEffect(() => {\n    window.addEventListener(\"scroll\", toggleVisible);\n  }, []);\n\n  function scrollToTop() {\n    window.scrollTo({\n      top: 0,\n      behavior: \"smooth\"\n    });\n  }\n  return (\n    <>\n      <div className=\"app-section\" id=\"home\">\n        <HomePage />\n      </div>\n      <div className=\"app-section\" id=\"about\">\n        <AboutPage />\n      </div>\n      <div className=\"app-section\" id=\"skills\">\n        <SkillPage />\n      </div>\n      <div className=\"app-section\" id=\"projects\">\n        <ProjectPage />\n      </div>\n      <div className=\"app-section\">\n        <EducationPage />\n      </div>\n      <div className=\"app-section-contact\" id=\"contact\">\n        <ContactPage />\n      </div>\n      {showBackToTopBtn && (\n        <button className=\"btn-back-to-top\" onClick={scrollToTop}>\n          <span> Back to Top</span>\n          <ArrowUpwardIcon />\n        </button>\n      )}\n    </>\n  );\n}"}],"source":"Vasu7389/react-project-ideas · by Lotus-7 · CC-BY-4.0"},"labex-react-developing-snake-game-with-react-hooks":{"intro":"In this challenge we will develop the snake game using react hooks like useState, useEffect, useRef along with the basic JS concepts.","steps":[{"title":"Snake Game","body":["To get started, open the editor. You can see the following files from your editor.","• To install the project dependencies, use the following command:","• Please complete this challenge in the src/App.js file. • The randomFoodPosition function is defined to generate a random position for the food item on the game board. • Inside the App function, there are several state variables defined using the useState hook: • snake represents the current state of the snake. • lastDirection represents the last direction the snake moved in. • foodPosition represents the current position of the food item. • isStarted determines if the game has started. • gameOver indicates if the game is over. • playgroundRef is a reference to the game board element.","Once you have completed the code, run it with the following command:"],"code":[{"lang":"txt","text":"├── public\n├── src\n│   ├── components\n│   │   ├── Food.js\n│   │   └── Snake.js\n│   ├── App.css\n│   ├── App.js\n│   ├── index.css\n│   └── index.js\n├── package-lock.json\n└── package.json"},{"lang":"bash","text":"npm start"}]}],"commands":["npm i","npm start"],"reference":[{"path":"App.js","text":"import { useEffect, useRef, useState } from \"react\";\nimport \"./App.css\";\nimport Food from \"./components/Food\";\nimport Snake from \"./components/Snake\";\n\nconst randomFoodPosition = () => {\n  const pos = { x: 0, y: 0 };\n  let x = Math.floor(Math.random() * 96);\n  let y = Math.floor(Math.random() * 96);\n  pos.x = x - (x % 4);\n  pos.y = y - (y % 4);\n  return pos;\n};\n\nconst initialSnake = {\n  snake: [\n    { x: 0, y: 0 },\n    { x: 4, y: 0 },\n    { x: 8, y: 0 }\n  ],\n  direction: \"ArrowRight\",\n  speed: 100\n};\n\nfunction App() {\n  const [snake, setSnake] = useState(initialSnake.snake);\n  const [lastDirection, setLastDirection] = useState(initialSnake.direction);\n  const [foodPosition, setFoodPosition] = useState(randomFoodPosition);\n  const [isStarted, setIsStarted] = useState(false);\n  const [gameOver, setGameOver] = useState(false);\n  const playgroundRef = useRef();\n\n  useEffect(() => {\n    if (!isStarted) return;\n\n    if (\n      snake[snake.length - 1].x === 100 ||\n      snake[snake.length - 1].x === 0 ||\n      snake[snake.length - 1].y === 100 ||\n      snake[snake.length - 1].y === -4\n    ) {\n      setGameOver(true);\n      return;\n    }\n    const interval = setInterval(move, initialSnake.speed);\n    return () => clearInterval(interval);\n  });\n\n  const move = () => {\n    const tmpSnake = [...snake];\n    let x = tmpSnake[tmpSnake.length - 1].x,\n      y = tmpSnake[tmpSnake.length - 1].y;\n    switch (lastDirection) {\n      case \"ArrowUp\":\n        y -= 4;\n        break;\n      case \"ArrowRight\":\n        x += 4;\n        break;\n      case \"ArrowDown\":\n        y += 4;\n        break;\n      case \"ArrowLeft\":\n        x -= 4;\n        break;\n      default:\n        break;\n    }\n\n    tmpSnake.push({\n      x,\n      y\n    });\n    if (x !== foodPosition.x || y !== foodPosition.y) tmpSnake.shift();\n    else setFoodPosition(randomFoodPosition());\n    setSnake(tmpSnake);\n  };\n\n  return (\n    <div\n      className=\"App\"\n      onKeyDown={(e) => setLastDirection(e.key)}\n      ref={playgroundRef}\n      tabIndex={0}\n    >\n      {isStarted && <div className=\"count\"> score: {snake.length - 3}</div>}\n\n      {!isStarted && (\n        <>\n          <button\n            onClick={() => {\n              setIsStarted(true);\n              playgroundRef.current.focus();\n            }}\n            type=\"submit\"\n          >\n            Start\n          </button>\n          <div className=\"arrow-msg text\">Press Arrows keys to play!</div>\n        </>\n      )}\n      {gameOver && (\n        <>\n          <div className=\"game-over text\">Game Over!</div>\n          <button\n            onClick={() => {\n              setIsStarted(true);\n              setGameOver(false);\n              setSnake(initialSnake.snake);\n              setLastDirection(initialSnake.direction);\n              playgroundRef.current.focus();\n            }}\n            type=\"submit\"\n          >\n            Restart\n          </button>\n        </>\n      )}\n      <Snake snake={snake} lastDirection={lastDirection} />\n      {!gameOver && (\n        <>\n          <Food position={foodPosition} />\n        </>\n      )}\n    </div>\n  );\n}\n\nexport default App;"}],"source":"Vasu7389/react-project-ideas · by Lotus-7 · CC-BY-4.0"},"labex-react-reactive-stopwatch-and-countdown-timer":{"intro":"In this challenge we will develop a react stopwatch & countdown timer(days, hours, minutes & seconds) using basic React concepts with little JavaScript programming logic around that.","steps":[{"title":"Stopwatch","body":["To get started, open the editor. You can see the following files from your editor.","• To install the project dependencies, use the following command:","Once you have completed the code, run it with the following command:","The finished result is as follows:"],"code":[{"lang":"txt","text":"├── public\n├── src\n│   ├── components\n│   │   ├──common\n│   │   ├── stopwatch\n│   │   ├── timer\n│   │   ├── App.css\n│   │   └── App.js\n│   ├── index.css\n│   └── index.js\n├── package-lock.json\n└── package.json"},{"lang":"bash","text":"npm start"}]}],"commands":["npm i","npm start"],"reference":[{"path":"Timer.js","text":"import React, { useEffect, useState } from \"react\";\nimport Button from \"../common/button/Button\";\nimport \"./Timer.css\";\n\nconst Timer = () => {\n  const [[h, m, s], setTimer] = useState([0, 0, 0]);\n  const [isStarted, setIsStarted] = useState(false);\n\n  useEffect(() => {\n    const timerID = setInterval(() => onStart(), 1000);\n    return () => {\n      clearInterval(timerID);\n    };\n  });\n\n  const onStart = () => {\n    if (h === 0 && m === 0 && s === 0) {\n      setIsStarted(false);\n      return;\n    }\n    if (!isStarted) return;\n    if (m === 0 && s === 0) {\n      setTimer([h - 1, 59, 59]);\n    } else if (s === 0) {\n      setTimer([h, m - 1, 59]);\n    } else {\n      setTimer([h, m, s - 1]);\n    }\n  };\n\n  const onReset = () => {\n    setIsStarted(false);\n    setTimer([0, 0, 0]);\n  };\n\n  return (\n    <div className=\"timer\">\n      <div className=\"timer-row\">\n        <div className=\"timer-border-ring\">\n          <div className=\"timer-border-ring-inner\"></div>\n        </div>\n        <div className=\"timer-input-title\">\n          <input\n            type=\"number\"\n            className=\"timer-input\"\n            value={h}\n            onChange={(e) => setTimer([e.target.value, m, s])}\n          />\n          <span>h</span>\n        </div>\n        <div className=\"timer-input-title\">\n          <input\n            type=\"number\"\n            className=\"timer-input\"\n            value={m}\n            onChange={(e) => setTimer([h, e.target.value, s])}\n          />\n          <span>m</span>\n        </div>\n        <div className=\"timer-input-title\">\n          <input\n            type=\"number\"\n            className=\"timer-input\"\n            value={s}\n            onChange={(e) => setTimer([h, m, e.target.value])}\n          />\n          <span>s</span>\n        </div>\n      </div>\n      <div className=\"button-row\">\n        <Button onClickHandler={onReset}>Reset</Button>\n        {isStarted ? (\n          <Button onClickHandler={() => setIsStarted(false)}>Pause</Button>\n        ) : (\n          <Button\n            onClickHandler={() => setIsStarted(true)}\n            disabled={h === 0 && m === 0 && s === 0}\n          >\n            Start\n          </Button>\n        )}\n      </div>\n    </div>\n  );\n};\n\nexport default Timer;"}],"source":"Vasu7389/react-project-ideas · by Lotus-7 · CC-BY-4.0"},"labex-react-tik-tac-toe":{"intro":"In this challenge you will learn how to develop a tic-tac-toe board game using react basic concepts with little JS programming logic around that.","steps":[{"title":"Tik Tac Toe","body":["To get started, open the editor. You can see the following files from your editor.","• To install the project dependencies, use the following command:","Once you have completed the code, run it with the following command:","The finished result is as follows:"],"code":[{"lang":"txt","text":"├── public\n├── src\n│   ├── components\n│   │   ├── common\n│   │   │   └── Utils.js\n│   │   ├── Board.js\n│   │   ├── Game.js\n│   │   └── Square.js\n│   ├── App.css\n│   ├── App.js\n│   ├── App.test.js\n│   ├── index.css\n│   ├── index.js\n│   ├── logo.svg\n│   ├── reportWebVitals.js\n│   └── setupTests.js\n├── package-lock.json\n└── package.json"},{"lang":"bash","text":"npm start"}]}],"commands":["npm i","npm start"],"reference":[{"path":"Game.js","text":"import React, { useState } from \"react\";\nimport { calculateWinner } from \"./common/Utils\";\nimport Board from \"./Board\";\n\nconst style = {\n  container: {\n    display: \"flex\",\n    flexDirection: \"column\",\n    alignContent: \"center\",\n    justifyContent: \"space-evenly\",\n    height: \"100%\"\n  },\n  info: {\n    fontSize: \"2rem\",\n    opacity: \"0.5\",\n    textShadow: \"5px 5px #424242\"\n  }\n};\n\nconst Game = () => {\n  //board state initial = [null,null,null,null,null,null,null,null,null]\n  const [board, setBoard] = useState(Array(9).fill(null));\n  //state to track next turn\n  const [xTurn, setXTurn] = useState(true);\n  //variable to find winner (otherwise equals to null)\n  const winner = calculateWinner(board);\n\n  //everytime checks if winner is present or clicked on marked square then just returns\n  //otherwise update board array's clicked index value with 'X' or 'O'\n  const handleClick = (i) => {\n    const tmpBoard = [...board];\n    if (!!winner || !!tmpBoard[i]) return;\n\n    tmpBoard[i] = xTurn ? \"X\" : \"O\";\n    setBoard(tmpBoard);\n    setXTurn(!xTurn);\n  };\n\n  const resetBoard = () => (\n    <button onClick={() => setBoard(Array(9).fill(null))}>Start Game</button>\n  );\n\n  return (\n    <div style={style.container}>\n      <p style={style.info}>\n        {winner ? \"Winner: \" + winner : \"Next Player: \" + (xTurn ? \"X\" : \"O\")}\n      </p>\n      <Board squares={board} handleClick={handleClick} />\n      <div>{resetBoard()}</div>\n    </div>\n  );\n};\n\nexport default Game;"}],"source":"Vasu7389/react-project-ideas · by Lotus-7 · CC-BY-4.0"}};
